void aRejectedUploadNeverOpensTheBody() {
    UploadOutcome outcome = flow.upload("0004f2000000-app.log", validHeaders(), OptionalLong.of(10), () -> {
        throw new AssertionError("body opened");
    });

    assertThat(outcome).isInstanceOfSatisfying(UploadOutcome.Rejected.class, rejected -> {
        assertThat(rejected.reason()).isEqualTo(Rejection.MAC_MISMATCH);
        assertThat(rejected.identity()).hasValueSatisfying(identity -> assertThat(identity.certSerial()).isEqualTo("03A5B1"));
        assertThat(rejected.key()).isEmpty();
        assertThat(rejected.size()).hasValue(10);
    });
    assertThat(storage.files()).isEmpty();
}

// The fixed clock gives both uploads the same millisecond, so the second meets the first one's key.
@Test
void aSecondUploadInTheSameMillisecondIsKeyExists() {
    upload("0004f2abcdef-app.log", validHeaders());

    UploadOutcome second = flow.upload("0004f2abcdef-app.log", validHeaders(), OptionalLong.of(5),
            () -> new ByteArrayInputStream("other".getBytes(StandardCharsets.US_ASCII)));

    assertThat(second).isInstanceOfSatisfying(UploadOutcome.Rejected.class, rejected -> {
        assertThat(rejected.reason()).isEqualTo(Rejection.KEY_EXISTS);
        assertThat(rejected.key()).contains(new ObjectKey(MAC, RECEIVED_AT, FileType.APP_LOG));
        assertThat(rejected.cause()).isEmpty();
    });
    assertThat(storage.files().values()).singleElement().satisfies(file -> assertThat(file.body()).isEqualTo(LOG_LINE));
}

@Test
void aStorageErrorIsStorageFailed() {
    LogStorageException failure = new LogStorageException("raw/...", new IllegalStateException("S3 down"));
    storage.failWith(failure);

    assertThat(upload("0004f2abcdef-app.log", validHeaders())).isInstanceOfSatisfying(UploadOutcome.Rejected.class,
            rejected -> {
                assertThat(rejected.reason()).isEqualTo(Rejection.STORAGE_FAILED);
                assertThat(rejected.cause()).containsSame(failure);
            });

